<script setup lang="ts">
import type { Report } from '~/types/lapormas'
definePageMeta({ layout: 'app', middleware: 'auth', title: 'Antrean Penanganan' })
const { state, takeReport } = useLaporMas()
const verified = computed<Report[]>(() => state.value.reports.filter((r: Report) => r.status === 'Terverifikasi').sort((a, b) => b.createdAt.localeCompare(a.createdAt)))
const working = computed<Report[]>(() => state.value.reports.filter((r: Report) => r.status === 'Ditangani').sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)))
const completed = computed(() => state.value.reports.filter((r: Report) => r.status === 'Selesai').length)
function take(id: string) { takeReport(id) }
</script>
<template><div class="page-stack"><div class="page-title-row"><div><div class="eyebrow">PUSAT OPERASIONAL · F006</div><h1>Antrean penanganan</h1><p>Kelola laporan yang sudah diverifikasi admin dan catat hasil tindak lanjut.</p></div></div><div class="stats-grid stats-three"><StatCard label="Siap ditangani" :value="verified.length" helper="Menunggu petugas" icon="◷" tone="amber"/><StatCard label="Sedang ditangani" :value="working.length" helper="Dalam tindak lanjut" icon="⌁" tone="blue"/><StatCard label="Selesai" :value="completed" helper="Semua laporan" icon="✓" tone="green"/></div><section class="panel"><div class="panel-heading"><div><div class="eyebrow">ANTREAN BARU</div><h3>Laporan siap ditangani</h3><p>Ambil laporan untuk memulai tindak lanjut.</p></div><span class="count-pill">{{ verified.length }} laporan</span></div><div v-if="verified.length" class="officer-list"><div v-for="report in verified" :key="report.id" class="officer-card"><div class="officer-priority" :class="`priority-bg-${report.priority.toLowerCase()}`">{{ report.priority.slice(0,1) }}</div><div class="officer-card-content"><div class="report-kicker">{{ report.category }} · {{ report.ticket }}</div><NuxtLink :to="`/app/laporan/${report.id}`"><h3>{{ report.title }}</h3></NuxtLink><p>{{ report.description }}</p><div class="report-meta"><span>⌖ {{ report.location }}</span><span>Pelapor: {{ report.ownerName }}</span></div></div><div class="officer-card-actions"><StatusBadge :status="report.status"/><button class="btn btn-primary btn-small" @click="take(report.id)">Ambil laporan →</button><NuxtLink :to="`/app/laporan/${report.id}`" class="subtle-link">Detail</NuxtLink></div></div></div><EmptyState v-else title="Tidak ada antrean baru" description="Laporan yang telah diverifikasi admin akan muncul di sini." icon="✓"/></section><section class="panel"><div class="panel-heading"><div><div class="eyebrow">DALAM PROSES</div><h3>Laporan yang sedang ditangani</h3><p>Buka detail untuk mencatat hasil penyelesaian.</p></div><span class="count-pill">{{ working.length }} aktif</span></div><div v-if="working.length" class="officer-list"><div v-for="report in working" :key="report.id" class="officer-card"><div class="officer-priority priority-bg-blue">↗</div><div class="officer-card-content"><div class="report-kicker">{{ report.category }} · {{ report.ticket }}</div><NuxtLink :to="`/app/laporan/${report.id}`"><h3>{{ report.title }}</h3></NuxtLink><p>{{ report.description }}</p><div class="report-meta"><span>⌖ {{ report.location }}</span><span>Pelapor: {{ report.ownerName }}</span></div></div><div class="officer-card-actions"><StatusBadge :status="report.status"/><NuxtLink :to="`/app/laporan/${report.id}`" class="btn btn-outline btn-small">Catat hasil →</NuxtLink></div></div></div><EmptyState v-else title="Belum ada penanganan aktif" description="Ambil laporan dari antrean baru untuk memulai."/></section><div class="privacy-note"><span>✳</span><div><b>Prioritaskan keselamatan</b><p>Jangan melakukan tindakan berisiko sendiri. Koordinasikan kejadian yang membutuhkan kewenangan khusus dengan pihak berwenang.</p></div></div></div></template>
